<template>
    <div class="slider-wrapper">
        <div class="slider-header">
            <span class="slider-title">Year Range</span>
            <span class="slider-selection">{{ startYear }} – {{ endYear }}</span>
        </div>
        <div ref="yearPicker" class="year-picker"></div>
    </div>
</template>

<script>
import * as d3 from 'd3';
import gsap from 'gsap';

export default {
  name: 'YearSlider',
  props: {
  },
  data() {
    return {
        highlightColor: "#6366f1",
        boundaryColor: "#4f46e5",
        startYear: 2015,
        endYear: 2018,
        x: null,
        labels: null,

    };
  },
  mounted() {
    this.$nextTick(() => {
      this.drawChart();
      this._resizeObserver = new ResizeObserver(() => {
        clearTimeout(this._resizeTimer);
        this._resizeTimer = setTimeout(() => this.drawChart(), 100);
      });
      this._resizeObserver.observe(this.$refs.yearPicker.parentElement);
    });
  },
  beforeDestroy() {
    if (this._resizeObserver) this._resizeObserver.disconnect();
    if (this._resizeTimer) clearTimeout(this._resizeTimer);
  },
  methods: {
    drawChart() {
      const years = d3.range(2013, 2023);
      const height = 54;
      const gap = 3;
      const wrapperWidth = this.$refs.yearPicker.parentElement.offsetWidth;
      const totalGaps = gap * (years.length - 1);
      const boxWidth = (wrapperWidth - totalGaps) / years.length;

      d3.select(this.$refs.yearPicker).selectAll('*').remove();

      const svg = d3.select(this.$refs.yearPicker)
        .append('svg')
        .attr('width', wrapperWidth)
        .attr('height', height);

      const x = d3.scalePoint()
        .domain(years)
        .range([0, wrapperWidth])
        .padding(1);

      this.x = x;

      const self = this;

      this.boxes = svg.selectAll('.year-box')
        .data(years)
        .enter()
        .append('rect')
        .attr('class', 'year-box')
        .attr('x', (_, i) => i * (boxWidth + gap))
        .attr('y', 0)
        .attr('width', boxWidth)
        .attr('height', height)
        .attr('rx', 9)
        .attr('fill', 'rgba(255, 255, 255, 0.58)')
        .attr('stroke', 'rgba(255, 255, 255, 0.85)')
        .attr('stroke-width', 1)
        .attr('cursor', 'pointer')
        .on('click', this.handleYearClick)
        .on('mouseover', function(_, d) {
          const isSelected = d >= self.startYear && d <= self.endYear;
          if (!isSelected) {
            gsap.to(this, { duration: 0.15, attr: { fill: 'rgba(255, 255, 255, 0.92)' }, ease: 'power2.out' });
          }
        })
        .on('mouseout', function(_, d) {
          const target = (d >= self.startYear && d <= self.endYear) ? self.highlightColor : 'rgba(255, 255, 255, 0.58)';
          gsap.to(this, { duration: 0.15, attr: { fill: target }, ease: 'power2.out' });
        });

      gsap.from(this.boxes.nodes(), { duration: 0.5, opacity: 0, stagger: 0.04, ease: 'power2.out' });

      this.labels = svg.selectAll('.year-label')
        .data(years)
        .enter()
        .append('text')
        .attr('class', 'year-label')
        .attr('x', (_, i) => i * (boxWidth + gap) + boxWidth / 2)
        .attr('y', height / 2)
        .attr('text-anchor', 'middle')
        .attr('alignment-baseline', 'middle')
        .attr('font-size', 13)
        .attr('font-family', "'JetBrains Mono', monospace")
        .attr('pointer-events', 'none')
        .attr('font-weight', '600')
        .attr('fill', '#334155')
        .text(d => d);

      this.updateHighlight();
    },
    handleYearClick(_event, year) {
      const years = [this.startYear, this.endYear].sort((a, b) => a - b);

      if (year < years[0] || year > years[1]) {
        // Expand selection to include year
        if (Math.abs(year - years[0]) < Math.abs(year - years[1])) {
          this.startYear = year;
        } else {
          this.endYear = year;
        }
      } else {
        // Reset selection to a single year
        this.startYear = year;
        this.endYear = year;
      }

      // Ensure correct order
      if (this.startYear > this.endYear) {
        const temp = this.startYear;
        this.startYear = this.endYear;
        this.endYear = temp;
      }

      this.updateHighlight();
      this.$store.commit('changeSelectedYearRange', {
        startYear: this.startYear,
        endYear: this.endYear,
      });
    },
    updateHighlight() {
      if (!this.x || !this.boxes) return;

      const self = this;

      this.boxes.each(function(d) {
        const isSelected = d >= self.startYear && d <= self.endYear;
        gsap.to(this, {
          duration: 0.3,
          attr: { fill: isSelected ? self.highlightColor : 'rgba(255, 255, 255, 0.58)' },
          ease: 'power2.inOut'
        });
      });

      if (this.labels) {
        this.labels.each(function(d) {
          const isSelected = d >= self.startYear && d <= self.endYear;
          const isBoundary = d === self.startYear || d === self.endYear;
          gsap.to(this, {
            duration: 0.3,
            attr: { fill: isSelected ? '#ffffff' : '#334155' },
            ease: 'power2.inOut'
          });
          d3.select(this).style('text-decoration', isBoundary ? 'underline' : 'none');
        });
      }
    }
  },
  computed: {
    selectedYearRange: {
      get() {
        return [this.startYear, this.endYear];
      },
      set([start, end]) {
        this.startYear = start;
        this.endYear = end;
        this.updateHighlight();
        this.$store.commit('changeSelectedYearRange', {startYear: start, endYear: end});
      },
    },
  },
  watch: {
    // startYear(val) {
    //   this.updateSliderBackground();
    //   if (val > this.endYear) this.endYear = val;
    //   this.$store.commit('changeSelectedYearRange', { startYear: this.startYear, endYear: this.endYear });
      
    // },
    // endYear(val) {
    //   this.updateSliderBackground();
    //   if (val < this.startYear) this.startYear = val;
    //   this.$store.commit('changeSelectedYearRange', { startYear: this.startYear, endYear: this.endYear });
    // },
  },
}
</script>

