<template>
  <div class="slider-wrapper">
    <div class="slider-header">
      <span class="slider-title">Year</span>
      <span class="slider-selection">{{ currentYear }}</span>
    </div>
    <div ref="yearPicker" class="year-picker"></div>
  </div>
</template>

<script>
import * as d3 from 'd3';
import gsap from 'gsap';

export default {
  name: 'YearSlider',
  data() {
    return {
      highlightColor: '#6366f1',
      boxes: null,
      labels: null,
    };
  },
  mounted() {
    this.$nextTick(() => {
      this.drawChart();
      this._resizeObserver = new ResizeObserver(() => {
        clearTimeout(this._resizeTimer);
        this._resizeTimer = setTimeout(() => this.drawChart(), 100);
      });
      this._resizeObserver.observe(this.$refs.yearPicker.parentElement);
    });
  },
  beforeDestroy() {
    if (this._resizeObserver) this._resizeObserver.disconnect();
    if (this._resizeTimer) clearTimeout(this._resizeTimer);
  },
  computed: {
    currentYear() {
      return this.$store.getters.selectedYear;
    },
  },
  watch: {
    currentYear() {
      this.updateHighlight();
    },
  },
  methods: {
    drawChart() {
      const years = d3.range(2013, 2023);
      const height = 54;
      const gap = 3;
      const wrapperWidth = this.$refs.yearPicker.parentElement.offsetWidth;
      const boxWidth = (wrapperWidth - gap * (years.length - 1)) / years.length;

      d3.select(this.$refs.yearPicker).selectAll('*').remove();

      const svg = d3.select(this.$refs.yearPicker)
        .append('svg')
        .attr('width', wrapperWidth)
        .attr('height', height);

      const self = this;

      this.boxes = svg.selectAll('.year-box')
        .data(years)
        .enter()
        .append('rect')
        .attr('class', 'year-box')
        .attr('x', (_, i) => i * (boxWidth + gap))
        .attr('y', 0)
        .attr('width', boxWidth)
        .attr('height', height)
        .attr('rx', 9)
        .attr('fill', 'rgba(255,255,255,0.58)')
        .attr('stroke', 'rgba(255,255,255,0.85)')
        .attr('stroke-width', 1)
        .attr('cursor', 'pointer')
        .on('click', this.handleYearClick)
        .on('mouseover', function(_, d) {
          if (d != self.currentYear) {
            gsap.to(this, { duration: 0.15, attr: { fill: 'rgba(255,255,255,0.92)' }, ease: 'power2.out' });
          }
        })
        .on('mouseout', function(_, d) {
          const target = d == self.currentYear ? self.highlightColor : 'rgba(255,255,255,0.58)';
          gsap.to(this, { duration: 0.15, attr: { fill: target }, ease: 'power2.out' });
        });

      gsap.from(this.boxes.nodes(), { duration: 0.5, opacity: 0, stagger: 0.04, ease: 'power2.out' });

      this.labels = svg.selectAll('.year-label')
        .data(years)
        .enter()
        .append('text')
        .attr('class', 'year-label')
        .attr('x', (_, i) => i * (boxWidth + gap) + boxWidth / 2)
        .attr('y', height / 2)
        .attr('text-anchor', 'middle')
        .attr('alignment-baseline', 'middle')
        .attr('font-size', 13)
        .attr('font-family', "'JetBrains Mono', monospace")
        .attr('pointer-events', 'none')
        .attr('font-weight', '600')
        .attr('fill', '#334155')
        .text(d => d);

      this.updateHighlight();
    },
    handleYearClick(_event, year) {
      this.$store.commit('changeSelectedYear', year);
    },
    updateHighlight() {
      if (!this.boxes) return;
      const selected = this.currentYear;
      const self = this;

      this.boxes.each(function(d) {
        gsap.to(this, {
          duration: 0.3,
          attr: { fill: d == selected ? self.highlightColor : 'rgba(255,255,255,0.58)' },
          ease: 'power2.inOut',
        });
      });

      if (this.labels) {
        this.labels.each(function(d) {
          gsap.to(this, {
            duration: 0.3,
            attr: { fill: d == selected ? '#ffffff' : '#334155' },
            ease: 'power2.inOut',
          });
        });
      }
    },
  },
};
</script>

<style scoped>
.slider-wrapper {
  position: relative;
  width: 100%;
  padding-top: 4px;
  padding-bottom: 14px;
  border-bottom: 1px solid rgba(99, 102, 241, 0.1);
  margin-bottom: 2px;
}

.slider-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 2px;
  margin-bottom: 8px;
}

.slider-title {
  font-family: 'Inter', sans-serif;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: #94a3b8;
}

.slider-selection {
  font-family: 'JetBrains Mono', monospace;
  font-size: 13px;
  font-weight: 500;
  color: #6366f1;
}

.year-picker {
  height: 54px;
}
</style>
