<template>
  <div class="vis-component" ref="chart">
    <div class="content-wrapper">
      <div class="setting-box">

        <div class="controls-bar">
          <!-- Detail level segmented control -->
          <div class="ctrl-group">
            <span class="ctrl-label">Detail</span>
            <div class="bin-checkboxes">
              <input type="radio" id="bin1" value="10" name="bins" checked>
              <label for="bin1">High</label>
              <input type="radio" id="bin2" value="30" name="bins">
              <label for="bin2">Med</label>
              <input type="radio" id="bin3" value="50" name="bins">
              <label for="bin3">Low</label>
            </div>
          </div>

          <!-- Compare year -->
          <div class="ctrl-group">
            <span class="ctrl-label">Compare</span>
            <select id="yearDropdown" class="styled-select">
              <option value="2013">2013</option>
              <option value="2014">2014</option>
              <option value="2015">2015</option>
              <option value="2016">2016</option>
              <option value="2017">2017</option>
              <option value="2018">2018</option>
              <option value="2019">2019</option>
              <option value="2020">2020</option>
              <option value="2021">2021</option>
              <option value="2022">2022</option>
            </select>
          </div>

          <button id="overlayToggle" class="toggle-btn">Overlay: OFF</button>

          <!-- Legend pushed to the right -->
          <div class="legend">
            <div class="legend-item">
              <span class="legend-dot" style="background:#6366f1;"></span>
              <span>Base data</span>
            </div>
            <div class="legend-item">
              <span class="legend-dot" style="background:#ef4444;"></span>
              <span>Average</span>
            </div>
            <div class="legend-item">
              <span class="legend-dot" style="background:#14b8a6;"></span>
              <span>Overlay</span>
            </div>
          </div>
        </div>

        <svg id="main-svg" :width="svgWidth" :height="550">
          <g class="chart-group" ref="chartGroup">
            <g class="axis axis-x" ref="axisX"></g>
            <g class="axis axis-y" ref="axisY"></g>
            <g class="bars-group" ref="barsGroup"></g>
          </g>
        </svg>

      </div>
    </div>
  </div>
</template>

<script>

import * as d3 from 'd3';
import gsap from 'gsap';
import {normalize} from './d3ComponentUltils';

export default {
  name: 'FlexBar',
  props: {
  },
  data() {
    return {
      numberOfCharts: 0, 
      totalChartWidth: 0,
      chartWidth: 0, 
      chartHeight: 0,
      
      translateY: 40,
      svgWidth: 0,
      svgHeight: 500,
      svgPadding: {
        top: 25, right: 20, bottom: 30, left: 40,
      },
      ypadding: 60,
      canvas: null,

      originalColors: {},
      selectedGroups: {},
      paddingBetweenCharts: 20,
      initialBins: 10,
      overlayEnabled: false,
    }
  },
  mounted() {
    this.$nextTick(() => {
      this.drawChart();
      this._resizeObserver = new ResizeObserver(() => {
        clearTimeout(this._resizeTimer);
        this._resizeTimer = setTimeout(() => this.drawChart(), 100);
      });
      this._resizeObserver.observe(this.$el.parentElement);
    });
  },
  beforeDestroy() {
    if (this._resizeObserver) this._resizeObserver.disconnect();
    if (this._resizeTimer) clearTimeout(this._resizeTimer);
  },
  methods: {
    sizeSetup() {
      const containerWidth = this.$el.parentElement.clientWidth - 24;
      this.svgWidth = containerWidth - 22; // minus .setting-box padding (10px × 2) + border (1px × 2)
      this.chartWidth = this.svgWidth - this.svgPadding.left - this.svgPadding.right;
      this.chartHeight = this.svgHeight - this.svgPadding.top - this.svgPadding.bottom;

      d3.select(this.$refs.chartGroup)
        .attr('transform', `translate(${this.svgPadding.left},${this.svgPadding.top})`);

      this.canvas = d3.select("#main-svg");
      this.canvas.selectAll(".tooltip-layer").remove();
      this.canvas.append("g").attr("class", "tooltip-layer");
    },
    drawChart() {
      if (!this.amsScore.length) return;

      this.sizeSetup();

      this.clearChart();

      let startYear = this.selectedYearRange.startYear;
      let endYear = this.selectedYearRange.endYear;

      let selectedRange = Object.keys(this.datasets)
        .filter(year => +year >= startYear && +year <= endYear)
        .reduce((result, year) => {
        
          result[year] = this.datasets[year];
          return result;
        }, {});
        
      // var overlaydata = this.amsScore2022;
      const selectedYear = d3.select("#yearDropdown").property("value");
      const selectedDataset = this.datasets[selectedYear];

      let lastPos = this.drawBars(selectedRange, selectedDataset);
      
      this.handleOverlay(lastPos);
      this.listeningBinChange(selectedRange, selectedDataset);
      this.drawLabels();
      this.enableDrag();
      
    },
    clearChart() {
      //reset bins
      d3.select('#bin1').property('checked', true);

      d3.select(".axislables").remove();
      d3.select(".background").remove();
      //reset charts
      d3.select(this.$refs.barsGroup).selectAll("*").remove();
    },
    drawLabels(){
      d3.selectAll(".axislables").remove();

      this.canvas.append("text")
        .attr("class", "axislables")
        .attr("x", 0)
        .attr("y", 28)
        .attr("font-size", "11px")
        .attr("font-family", "'Inter', sans-serif")
        .attr("font-weight", "600")
        .attr("letter-spacing", "0.06em")
        .attr("fill", "#94a3b8")
        .text("INDIVIDUALS");

      this.canvas.append("text")
        .attr("class", "axislables")
        .attr("x", this.svgPadding.left + this.totalChartWidth - 10)
        .attr("y", 550)
        .attr("font-size", "11px")
        .attr("font-family", "'Inter', sans-serif")
        .attr("font-weight", "600")
        .attr("letter-spacing", "0.06em")
        .attr("text-anchor", "end")
        .attr("fill", "#94a3b8")
        .text("SCORE");
    },
    enableDrag(){
        const chartWidth = this.chartWidth / this.numberOfCharts;
        
        const drag = d3.drag()
        .on('drag', (event) => {
            const dx = event.dx;
            let transform = d3.select('.overlay').attr('transform');
            let translateX = 0;

            if (transform) {
                const translateMatch = transform.match(/translate\(([^,]+),([^)]+)\)/);
                
                if (translateMatch) {
                    translateX = parseFloat(translateMatch[1]) + dx;
                }
            }

            //console.log("current", translateMatch)
            
            d3.select('.overlay')
                .attr('transform', `translate(${translateX},0)`);
        })
        .on('end', () => {
            
            let transform = d3.select('.overlay').attr('transform');
            var currentx = 0;
            if(transform){
                const translateMatch = transform.match(/translate\(([^,]+),([^)]+)\)/);
                if (translateMatch) {
                    currentx = parseFloat(translateMatch[1]);
                }
                
            }
            
            const snaptolerance = chartWidth / 2;
            let block = -chartWidth - 20;

            for (let i = 0; i< this.numberOfCharts - 1; i++) {
                if(Math.abs(currentx) >= i * Math.abs(block) + snaptolerance) {
                    d3.select('.overlay').transition().duration(500).attr('transform', `translate(${(i+1) * block}, 0)`);
                    
                }
            }
            
           
            if (Math.abs(currentx) < snaptolerance) {
                d3.select('.overlay').transition().duration(500).attr('transform', `translate(0, 0)`);
            } 
  

        });

        this.canvas.call(drag);
    },
    drawHistogram({ binnum, data, xpos, classname, color, opacity, overlaydata, barsGroup}){
            let opacityLine = 1;
            //changed here
            const x = d3.scaleLinear()
                .domain([0, 100])
                .range([0, this.chartWidth / this.numberOfCharts]);

            const histogram = d3.histogram()
                .value(d => d.value )
                .domain(x.domain())
                .thresholds(x.ticks(binnum));

            var bins = histogram(data);

            //this here updates the bin for overlay
            if(overlaydata && !data){
                bins = histogram(overlaydata);
                opacityLine = 0.3;
            }
            
            const yQuantity = d3.scaleLinear()
                .range([this.chartHeight, 0])
                .domain([0, 130]);

            const totalCount = d3.sum(bins, d => d.length);

            if(d3.select("."+classname).empty()){
                barsGroup.append("g").attr("class", classname); 
            }

            // Clear any existing bars and axes before drawing new ones
            let bargroup = d3.select("."+classname);
            bargroup.selectAll("*").remove();

            // Draw the y-axis (and gridlines) first so x-axis renders on top
            let yAxis = d3.selectAll(".yaxis");
            if (yAxis.empty()) {
                yAxis = bargroup.append("g")
                  .attr("transform", `translate(${0},${this.translateY})`)
                  .attr("class", "yaxis");
            }
            yAxis.call(
              d3.axisLeft(yQuantity)
              .tickSize(-this.totalChartWidth)
              .tickFormat(d => d)
            )
            .selectAll(".tick")
            .each(function(d) {
              if (d === 0) {
                 d3.select(this).select("line").attr("stroke", "#f1f5f9");
              } else {
                d3.select(this).select("line").attr("stroke", "#cbd5e1");
              }
            });

            // Style y-axis tick labels
            yAxis.selectAll("text")
              .style("font-size", "11px")
              .style("font-family", "'JetBrains Mono', monospace")
              .style("fill", "#94a3b8");
            yAxis.select(".domain").attr("stroke", "none");

            bins.forEach((d, i) => { d.binIndex = i });
            
            // Draw the bars
            bargroup
                .selectAll("rect")
                .data(bins)
                .enter()
                .append("rect")
                .attr("class", (d, i) => `bin-group bin-${i}`)
                .attr("x", xpos)
                .attr("transform", d => `translate(${x(d.x0)},${yQuantity(d.length) + this.translateY})`)
                .attr("width", d => x(d.x1) - x(d.x0) - 1)
                .attr("height", d => this.chartHeight - yQuantity(d.length))
                .style("fill", color)
                .style("opacity", opacity)
                .on("mouseenter", function(event, d) {
                  const hoveredBinIndex = d.binIndex;

                  // GSAP: spotlight — dim non-matching bins
                  d3.selectAll('.bin-group').each(function(binD) {
                    gsap.to(this, {
                      opacity: binD.binIndex === hoveredBinIndex ? 1 : 0.2,
                      duration: 0.18,
                      ease: 'power2.out'
                    });
                  });

                  let tooltipLayer = d3.select(".tooltip-layer");
                  let tooltipGroup = tooltipLayer.select(".tooltip-group");
                  if (tooltipGroup.empty()) {
                    tooltipLayer.append("g").attr("class", "tooltip-group");
                  }

                  d3.selectAll(".bin-group")
                    .each(function(binData) {
                      if (binData.binIndex === hoveredBinIndex) {
                        const binWidth = x(binData.x1) - x(binData.x0);
                        const chartX = +d3.select(this).attr("x") || 0;
                        const barX = x(binData.x0);
                        const barY = yQuantity(binData.length) + 40;

                        const posX = chartX + barX + 2 * binWidth + 23;
                        const posY = barY + 30;

                        const count = binData.length;
                        const rangeStart = (binData.x0 * 100).toFixed(0);
                        const rangeEnd = (binData.x1 * 100).toFixed(0);
                        const pct = (count / totalCount * 100).toFixed(1);

                        // Label row
                        const labelEl = tooltipGroup.append("text")
                          .attr("x", posX + 12)
                          .attr("y", posY)
                          .attr("font-family", "'Inter', sans-serif")
                          .attr("font-size", "10px")
                          .attr("font-weight", "600")
                          .attr("letter-spacing", "0.06em")
                          .attr("fill", "#94a3b8")
                          .text(`SCORE ${rangeStart}–${rangeEnd}`);

                        // Count value
                        const countEl = tooltipGroup.append("text")
                          .attr("x", posX + 12)
                          .attr("y", posY + 18)
                          .attr("font-family", "'JetBrains Mono', monospace")
                          .attr("font-size", "18px")
                          .attr("font-weight", "600")
                          .attr("fill", "#1e293b")
                          .text(count);

                        // Pct sub-label
                        const pctEl = tooltipGroup.append("text")
                          .attr("x", posX + 12)
                          .attr("y", posY + 34)
                          .attr("font-family", "'Inter', sans-serif")
                          .attr("font-size", "11px")
                          .attr("font-weight", "500")
                          .attr("fill", "#6366f1")
                          .text(`${pct}% of ${totalCount}`);

                        const bbox = countEl.node().getBBox();
                        const allBbox = pctEl.node().getBBox();
                        const boxWidth = Math.max(bbox.width, allBbox.width, labelEl.node().getBBox().width) + 28;
                        const boxHeight = 52;

                        tooltipGroup.insert("rect", "text")
                          .attr("x", posX)
                          .attr("y", posY - 14)
                          .attr("width", boxWidth)
                          .attr("height", boxHeight)
                          .attr("rx", 10)
                          .attr("fill", "rgba(255,255,255,0.95)")
                          .attr("stroke", "rgba(99,102,241,0.18)")
                          .attr("stroke-width", 1)
                          .attr("class", "tooltipbox");

                        // Indigo accent bar on left edge
                        tooltipGroup.insert("rect", "text")
                          .attr("x", posX)
                          .attr("y", posY - 14)
                          .attr("width", 3)
                          .attr("height", boxHeight)
                          .attr("rx", 10)
                          .attr("fill", "#6366f1")
                          .attr("class", "tooltipbox");

                        // Fade in
                        const nodes = tooltipGroup.selectAll("*").nodes();
                        gsap.fromTo(nodes, { opacity: 0 }, { opacity: 1, duration: 0.2, ease: 'power2.out', stagger: 0.02 });
                      }
                    });
                })
                .on("mouseout", function() {
                  d3.selectAll('.bin-group').each(function() {
                    gsap.to(this, { opacity: 1, duration: 0.22, ease: 'power2.out' });
                  });
                  d3.selectAll(".tooltip-group").selectAll("*").remove();
                  d3.selectAll(".tooltipbox").remove();
                });

                //this is shit code 
                if(overlaydata && !data){
                  d3.selectAll(".bin-group")
                    .on("mouseenter", null)
                    .on("mouseout", null);
                }

                const dataset = data || overlaydata;
                const avgScore = d3.mean(dataset, d => d.value);
                
                // Draw vertical average line
                bargroup.append("line")
                    .attr("x1", xpos + x(avgScore))
                    .attr("x2", xpos + x(avgScore))
                    .attr("y1", this.translateY)
                    .attr("y2", this.chartHeight + this.translateY)
                    .attr("stroke-opacity", opacityLine)
                    .attr("stroke", "#ef4444")
                    .attr("stroke-width", 1.5)
                    .attr("stroke-dasharray", "4,3")
                    .attr("class", "average-line");

                // Average score label
                bargroup.append("text")
                    .attr("x", xpos + x(avgScore))
                    .attr("y", this.translateY - 6)
                    .attr("text-anchor", "middle")
                    .attr("font-size", "11px")
                    .attr("font-family", "'JetBrains Mono', monospace")
                    .attr("font-weight", "600")
                    .attr("fill", "#ef4444")
                    .text(`${(avgScore).toFixed(2)}`)
                    .attr("class", "average-label");

                // Draw x-axis LAST so it renders on top of y-axis gridlines
                bargroup.append("g")
                    .attr("transform", `translate(${xpos},${this.chartHeight + this.translateY})`)
                    .call(d3.axisBottom(x).tickFormat(d => d))
                    .call(g => g.select(".domain").attr("stroke", "#cbd5e1"))
                    .selectAll("text")
                    .style("font-size", "11px")
                    .style("font-family", "'JetBrains Mono', monospace")
                    .style("fill", "#94a3b8");
    },
    drawBars(datasets, overlaydata) {
        const selectedBin = d3.select('.bin-checkboxes input[type="radio"]:checked').property('value');
        let binCount = +selectedBin;

        const numYears = Object.entries(datasets).length;
        this.numberOfCharts = numYears + 1;

        // Distribute full available width across visible year charts only.
        // chartWidth is set so that chartWidth/numberOfCharts = perChartWidth,
        // keeping all downstream drawHistogram / drag / overlay math unchanged.
        const availableWidth = this.svgWidth - this.svgPadding.left - this.svgPadding.right;
        const perChartWidth = (availableWidth - (numYears - 1) * this.paddingBetweenCharts) / numYears;
        this.chartWidth = perChartWidth * this.numberOfCharts;

        this.totalChartWidth = perChartWidth * numYears + (numYears - 1) * this.paddingBetweenCharts;

        let chartpos = 0;

        for (let [year, data] of Object.entries(datasets)) {
            this.drawHistogram({
              binnum: binCount,
              data,
              xpos: chartpos,
              classname: "group-" + year,
              color: "rgba(99, 102, 241, 0.78)",
              opacity: 1,
              overlaydata,
              barsGroup: d3.select(this.$refs.barsGroup),
            });

            d3.select(".group-" + year)
              .append("text")
              .attr("x", chartpos + perChartWidth / 2 - 4)
              .attr("y", 19)
              .text(year)
              .attr("font-size", "13px")
              .attr("font-family", "'Inter', sans-serif")
              .attr("font-weight", "600")
              .attr("fill", "#334155")
              .attr("text-anchor", "middle");

            chartpos = chartpos + perChartWidth + this.paddingBetweenCharts;
        }
        return chartpos;
    },
    listeningBinChange(datasets, overlaydata){
      //updating with bin numbers
        d3.selectAll('.bin-checkboxes input[type="radio"]').on('change', () => {
          const selectedBin = d3.select('.bin-checkboxes input[type="radio"]:checked').property('value');
          let binCount = +selectedBin;

          //redrawn here (after udating the bins): 
            let chartpos = 0;
            for (let [year, data] of Object.entries(datasets)) {
              this.drawHistogram({
                binnum: binCount,
                data,
                xpos: chartpos,
                classname: "group-" + year,
                color: "rgba(99, 102, 241, 0.78)",
                opacity: 1,
                overlaydata,
                barsGroup: d3.select(this.$refs.barsGroup),
            });

            d3.select(".group-" + year)
            .append("text")
            .attr("x", chartpos + this.chartWidth / this.numberOfCharts / 2 - 4)
            .attr("y", 19)
            .text(year)
            .attr("font-size", "13px")
            .attr("font-family", "'Inter', sans-serif")
            .attr("font-weight", "600")
            .attr("fill", "#334155")
            .attr("text-anchor", "middle");

            chartpos = chartpos + this.chartWidth / this.numberOfCharts + this.paddingBetweenCharts;
          }

          // this.drawOverlay(binCount, chartpos, overlaydata)
        })
      
    },
    drawOverlay(bincount, lastPos, overlaydata) {
        const selectedYear = d3.select("#yearDropdown").property("value");

      //draw the overlay data here
        this.drawHistogram({
          binnum: bincount,
          data: false,
          xpos: lastPos - this.chartWidth/this.numberOfCharts - this.paddingBetweenCharts,
          classname: "overlay",
          color: "#14b8a6",
          opacity: 0.9,
          overlaydata,
          barsGroup: d3.select(this.$refs.barsGroup),
        });

        // Dashed border around the entire overlay area — the drag affordance
        const areaLeft = lastPos - this.chartWidth/this.numberOfCharts - this.paddingBetweenCharts;
        const areaWidth = this.chartWidth / this.numberOfCharts;
        const areaHeight = this.chartHeight + this.translateY;
        const centerX = areaLeft + areaWidth / 2;

        // Transparent hit-target (keeps draggable area large)
        d3.select(".overlay")
          .append("rect")
          .attr("x", areaLeft)
          .attr("y", 0)
          .attr("width", areaWidth)
          .attr("height", areaHeight)
          .attr("fill", "transparent")
          .attr("cursor", "grab");

        // Dashed indigo border
        d3.select(".overlay")
          .append("rect")
          .attr("x", areaLeft)
          .attr("y", 0)
          .attr("width", areaWidth)
          .attr("height", areaHeight)
          .attr("fill", "rgba(20,184,166,0.04)")
          .attr("stroke", "#14b8a6")
          .attr("stroke-width", 1.5)
          .attr("stroke-dasharray", "6,4")
          .attr("rx", 8)
          .attr("pointer-events", "none");

        // Pill badge — year label centered at top
        const pillW = 52;
        const pillH = 22;
        d3.select(".overlay")
          .append("rect")
          .attr("x", centerX - pillW / 2)
          .attr("y", -pillH / 2 - 1)
          .attr("width", pillW)
          .attr("height", pillH)
          .attr("rx", pillH / 2)
          .attr("fill", "#0d9488")
          .attr("pointer-events", "none");

        d3.select(".overlay")
          .append("text")
          .attr("x", centerX)
          .attr("y", 9)
          .attr("text-anchor", "middle")
          .attr("font-size", "12px")
          .attr("font-family", "'JetBrains Mono', monospace")
          .attr("font-weight", "600")
          .attr("fill", "#ffffff")
          .attr("pointer-events", "none")
          .text(selectedYear);

    },
    handleOverlay(lastPos) {
      
      let self = this;  
      d3.select("#overlayToggle").on("click", ()=> {

        const selectedYear = d3.select("#yearDropdown").property("value");
        const selectedDataset = this.datasets[selectedYear];

        let startYear = this.selectedYearRange.startYear;
        let endYear = this.selectedYearRange.endYear;

        let selectedRange = Object.keys(this.datasets)
          .filter(year => +year >= startYear && +year <= endYear)
          .reduce((result, year) => {
          
            result[year] = this.datasets[year];
            return result;
          }, {});

        const selectedBin = d3.select('.bin-checkboxes input[type="radio"]:checked').property('value');
        // console.log("clicked?")
        // console.log(selectedYear)
        let binCount = +selectedBin;
        this.overlayEnabled = !this.overlayEnabled;
        const button = d3.select("#overlayToggle");
        
        button.text(this.overlayEnabled ? "Overlay: ON" : "Overlay: OFF");

        if (this.overlayEnabled) {
          button.classed("active", true);

          // Remove mouse events and clear tooltips
          d3.selectAll(".bin-group").on("mouseenter", null).on("mouseout", null);
          d3.selectAll(".tooltip-group").selectAll("*").remove();
          d3.selectAll(".tooltipbox").remove();

          // Draw overlay then GSAP animate it in
          self.drawOverlay(binCount, lastPos, selectedDataset);

          // Dim + desaturate base data bars
          d3.selectAll('.bin-group').each(function() {
            const parentClass = d3.select(this.parentNode).attr('class') || '';
            if (!parentClass.includes('overlay')) {
              gsap.to(this, { opacity: 0.55, duration: 0.45, ease: 'power2.out' });
              d3.select(this).selectAll('rect').each(function() {
                gsap.to(this, { duration: 0.45, attr: { fill: 'rgba(148,163,184,0.55)' }, ease: 'power2.out' });
              });
            }
          });

          // Fade overlay in
          const overlayNode = d3.select(this.$refs.barsGroup).select('.overlay').node();
          if (overlayNode) {
            gsap.fromTo(overlayNode, { opacity: 0 }, { opacity: 1, duration: 0.45, ease: 'power2.out' });
          }

        } else {
          button.classed("active", false);

          // Restore base bar color and opacity
          d3.selectAll('.bin-group').each(function() {
            const parentClass = d3.select(this.parentNode).attr('class') || '';
            if (!parentClass.includes('overlay')) {
              gsap.to(this, { opacity: 1, duration: 0.3, ease: 'power2.out' });
              d3.select(this).selectAll('rect').each(function() {
                gsap.to(this, { duration: 0.3, attr: { fill: 'rgba(99,102,241,0.78)' }, ease: 'power2.out' });
              });
            }
          });

          // Fade overlay out, then redraw base bars
          const overlayNode = d3.select(this.$refs.barsGroup).select('.overlay').node();
          if (overlayNode) {
            gsap.to(overlayNode, {
              opacity: 0, duration: 0.3, ease: 'power2.in',
              onComplete: () => {
                d3.selectAll(".overlay").remove();
                self.drawBars(selectedRange, selectedDataset);
              }
            });
          } else {
            d3.selectAll(".overlay").remove();
            self.drawBars(selectedRange, selectedDataset);
          }
        }
      });
    },
    handleBarClick(val) {
      this.$store.commit('changeSelectedState', val);
    }
  },
  computed: {
    datasets() {
    const years = ['2013', '2014', '2015', '2016', '2017', '2018', '2019', '2020', '2021', '2022'];
    return years.reduce((acc, year) => ({
      ...acc,
      [year]: normalize(this.$store.getters.amsScoreByYear(year))
    }), {});
    },
    selectedYearRange() {
      return this.$store.getters.selectedYearRange;
    },
    amsScore:{
      get() {
        return this.$store.getters.amsScore;
      }
    },
    fullFeature:{
      get() {
        return this.$store.getters.fullFeature;
      }
    },
    personaleIncome: {
      get() {
        return this.$store.getters.personaleIncome;
      }
    },
    amsScore2013() {
      return this.$store.getters.amsScoreByYear("2013");
    },
    amsScore2014() {
      return this.$store.getters.amsScoreByYear("2014");
    },
    amsScore2015() {
      return this.$store.getters.amsScoreByYear("2015");
    },
    amsScore2016() {
      return this.$store.getters.amsScoreByYear("2016");
    },
    amsScore2017() {
      return this.$store.getters.amsScoreByYear("2017");
    },
    amsScore2018() {
      return this.$store.getters.amsScoreByYear("2018");
    },
    amsScore2019() {
      return this.$store.getters.amsScoreByYear("2019");
    },
    amsScore2020() {
      return this.$store.getters.amsScoreByYear("2020");
    },
    amsScore2021() {
      return this.$store.getters.amsScoreByYear("2021");
    },
    amsScore2022() {
      return this.$store.getters.amsScoreByYear("2022");
    },
  },
  watch: {
    amsScore: {
      handler() {
        this.drawChart();
      },
      deep: true,
    },
    selectedYearRange: {
      handler() {
        this.drawChart();
      },
      deep: true,
    },
  },
}
</script>

