<template>
  <div class="vis-component" ref="chart">
    <div class="content-wrapper">

      <div class="sidebar">
        <div class="sidebar-header">
          <span class="sidebar-title">Filters</span>
        </div>
        <div class="legende_filter">
          <div v-for="(options, category) in filterOptions" :key="category">
            <label class="category_label">{{ category }}</label>
              <div v-for="option in options" :key="option" class="checkbox-container" @click="toggleSelection(category, option)">
                <div class="custom-check" :class="{ 'is-checked': isSelected(category, option) }">
                  <svg class="check-svg" viewBox="0 0 12 12">
                    <polyline points="2,6 5,9 10,3"/>
                  </svg>
                </div>
                <label>{{ option }}</label>
              </div>
          </div>
      </div>
        
    </div>

    
      <div class="scatter-wrapper" ref="scatterPanel">
            <svg id="main-svg" :width="svgWidth" :height="svgHeight">
                <g class="chart-group" ref="chartGroup">
                <g class="axis axis-x" ref="axisX"></g>

                <g class="axis axis-y" ref="axisY"></g>
                <g ref="axisYMe"></g>
                <g ref="axisYPDM1"></g>
                <g ref="axisYPDM2"></g>

                <g class="bars-group-2" ref="barsGroup"></g>
                </g>
            </svg>

            <div class="density-row">
              <button
                  :class="['toggle-switch-btn', { active: currentMode === 'density' }]"
                  @click="toggleDensity"
                  >
                  {{ currentMode === 'density' ? 'Density: ON' : 'Density: OFF' }}
              </button>
              <div class="hint-badge">
                ?
                <div class="hint-tooltip">
                  Spreads dots horizontally so you can compare how you and your colleagues scored the same individuals.
                  Click any dot to see that person's detailed benefit score breakdown.
                </div>
              </div>
            </div>
        </div>

        <div class="bar-wrapper" ref="barPanel">
            <transition name="empty-fade">
              <div v-if="!hasSelection" class="empty-state">
                <svg width="56" height="56" viewBox="0 0 56 56" fill="none" class="empty-icon">
                  <circle cx="14" cy="38" r="5" fill="#e2e8f0"/>
                  <circle cx="30" cy="22" r="5" fill="#e2e8f0"/>
                  <circle cx="44" cy="34" r="5" fill="#e2e8f0"/>
                  <circle cx="30" cy="22" r="11" stroke="#6366f1" stroke-width="1.5" stroke-dasharray="3 2.5" fill="none" opacity="0.5"/>
                  <circle cx="30" cy="22" r="5" fill="#6366f1"/>
                </svg>
                <p class="empty-title">Select an individual</p>
                <p class="empty-hint">Click any dot in density mode to view their detailed score breakdown</p>
              </div>
            </transition>
            <svg id="second-svg" :width="barSvgWidth" :height="svgHeight">

            </svg>
        </div>

      
      </div>
    </div>

</template>

<script>

import * as d3 from 'd3';
import gsap from 'gsap';
import { fillPidsPerCategory, findcommonpids, linkProfileCard, normalize, computeDensityPositions} from './d3ComponentUltils';
// import { profile } from 'console';

export default {
  name: 'BarChart',
  props: {
  },
  data() {
    return {
      svgWidth: 0,
      svgHeight: 500,
      chartWidth: 0,
      barSvgWidth: 0,
      svgPadding: {
        top: 0, right: 20, bottom: 30, left: 40,
      },
      ypadding: 60,
      originalColors: {},
      originalColors_1: {},
      originalColors_2: {},
      profile: {
        pid: "",
        gender: "",
        citizenship: "",
        age: "",
        skill: "",
        impairment: "",
        occupation: "",
        dutycare: "",
        pool: 0,
      },
      filterOptions: {
        gender: ['male', 'female'],
        dutycare: ['Yes', 'No'],
        age: ['15-29', '30-44', '45-59', '60-74', '75-100'],
        skill: ['not stated', 'Compulsory', 'Apprenticeship', 'high school', 'university'],
        impairment: ['Yes', 'No'],
        citizenship: ['AT', 'EU', 'Non-EU'],
        occupation: ['agriculture', 'production', 'service', 'other'],
        
      },
      selectedGroups: {
        gender: [],
        citizenship: [],
        age: [],
        skill: [],
        impairment: [],
        occupation: [],
        dutycare: [],
      },
      currentMode: "default",
      shouldAnimate: false,
      filterbuttonClick: false,
      densityMode: false,
      selectedDots: [],
      normalizedDetailedScore: [],
      individualScore: 0,
      features: [
        { id: "feature_zero", value: 0, name: "Gender"},
        { id: "feature_one", value: 0, name: "Citizenship"},
        { id: "feature_two", value: 0, name: "Age"},
        { id: "feature_three", value: 0, name: "Education Lvl."},
        { id: "feature_four", value: 0, name: "Impairment"},
        { id: "feature_five", value: 0, name: "Occupation"},
        { id: "feature_six", value: 0, name: "Dutycare"}
      ],
    }
  },
  mounted() {
    this.$nextTick(() => {
      this.drawChart();

      this._resizeObserver = new ResizeObserver(() => {
        clearTimeout(this._resizeTimer);
        this._resizeTimer = setTimeout(() => this.drawChart(), 100);
      });
      this._resizeObserver.observe(this.$refs.chart);
    });
  },
  beforeDestroy() {
    if (this._resizeObserver) this._resizeObserver.disconnect();
    if (this._resizeTimer) clearTimeout(this._resizeTimer);
  },
  methods: {
    isSelected(category, option) {
      // return this.selectedGroups[category] === option;
      return this.selectedGroups[category]?.includes(option);
    },    
    toggleSelection(category, option) {
      if (!Array.isArray(this.selectedGroups[category])) {
        // Initialize as an empty array if not already
        this.$set(this.selectedGroups, category, []);
      }

      const index = this.selectedGroups[category].indexOf(option);

      if (index > -1) {
        // Deselect: remove option from array
        this.selectedGroups[category].splice(index, 1);
      } else {
        // Select: add option to array
        this.selectedGroups[category].push(option);
      }

      this.filterbuttonClick = true;
      this.filteredDotsRedraw();
    },
    toggleDensity() {
        this.currentMode = this.currentMode === 'default' ? 'density' : 'default';
        this.filterbuttonClick = false;
        this.shouldAnimate = true; 
        
        this.filteredDotsRedraw();  // Redraw with the new mode
        
    },
    filteredDotsRedraw(){
        //remove warning messages
        d3.select(".warning").remove();
        d3.select(".warning_1").remove();
        d3.select(".warning_2").remove();

        const datasets = [this.fullFeature, this.fullFeature_pdm1, this.fullFeature_pdm2];
        
        let allpdms = fillPidsPerCategory(datasets, this.filterOptions, this.selectedGroups);
        
        //find intersection between all the lists for all different pdms
        let intersection_me = findcommonpids(Object.values(allpdms[0]));
        let intersection_1 = findcommonpids(Object.values(allpdms[1]));
        let intersection_2 = findcommonpids(Object.values(allpdms[2]));
        
        let filteredDataArray = [];
        const config = [
            { name: "Me", data: normalize(this.amsScore), intersection: intersection_me, warningClass: "warning" },
            { name: "PDM1", data: normalize(this.amsScore_1), intersection: intersection_1, warningClass: "warning_1" },
            { name: "PDM2", data: normalize(this.amsScore_2), intersection: intersection_2, warningClass: "warning_2" },
        ];

        config.forEach(({ name, data, intersection, warningClass }) => {
            //need to convert to string, intersection & data have different pid type
            const filteredData = data.filter(d => intersection.map(String).includes(d.pid));
            filteredDataArray.push(filteredData);

            if (intersection.length === 0) {
              const barsGroup = d3.select(this.$refs.barsGroup);

              barsGroup
                .append("text")
                .attr("class", warningClass)
                .attr("x", this.xScale(name) + this.xScale.bandwidth() / 2 - 60)
                .attr("y", 23)
                .attr("fill", "#f59e0b")
                .attr("font-size", "11px")
                .attr("font-family", "'Inter', sans-serif")
                .text("(Note: no user found)");
            }
        });
        //redrawfiltered data
        this.drawScatterPlot(filteredDataArray[0], filteredDataArray[1], filteredDataArray[2], this.currentMode)
    },
    sizeSetup() {
      if (this.$refs.scatterPanel) {
        this.svgWidth = this.$refs.scatterPanel.clientWidth;
        this.chartWidth = this.svgWidth - this.svgPadding.left - this.svgPadding.right;
      }
      if (this.$refs.barPanel) {
        this.barSvgWidth = this.$refs.barPanel.clientWidth;
      }
      // section padding 24px + section header ~46px + year slider ~76px + density row ~52px
      const overhead = 24 + 46 + 76 + 52;
      this.svgHeight = Math.max(380, window.innerHeight - overhead);
      d3.select(this.$refs.chartGroup).attr('transform', `translate(${this.svgPadding.left},${this.svgPadding.top})`);
    },
    reset() {
      this.shouldAnimate = false;
      this.filterbuttonClick = false;
      this.currentMode = 'default';

      this.selectedGroups = {
        gender: "",
        citizenship: "",
        age: "",
        skill: "",
        impairment: "",
        occupation: "",
        dutycare: "",
      };

      this.individualScore = 0;
      this.selectedDots = [];
      this.profile = {
        pid: "", gender: "", citizenship: "", age: "",
        skill: "", impairment: "", occupation: "", dutycare: "", pool: 0,
      };
      for (const f of this.features) f.value = 0;
    },
    drawChart() {
      if (!this.amsScore.length || !this.amsScore_1.length || !this.amsScore_2.length) return;
      this.sizeSetup();
      this.reset();

      this.drawXAxis();
      this.drawYAxis();
      
      this.createNoise();
      this.drawScatterPlot(normalize(this.amsScore), normalize(this.amsScore_1), normalize(this.amsScore_2));
      this.drawBars();
        
    },
    createNoise(){
      
      // const elderlydPids = this.fullFeature_pdm2
      //   .filter(item => item.value[2] > 60)
      //   .map(item => item.pid);


      if(this.amsScore_2[0].year === '2017'){
        
        this.amsScore_2.forEach(item => {
          item.value += 1;
          // if(elderlydPids.includes(item.pid)){
          //   item.value += 1;
          // }
        });
      } 
    },
    drawXAxis() {
      const axisG = d3.select(this.$refs.axisX)
        .attr('transform', `translate(0, ${this.svgHeight - this.svgPadding.top - this.svgPadding.bottom})`)
        .call(d3.axisBottom(this.xScale).tickSize(4).tickFormat(d => {
          if (d === 'PDM1') return 'Colleague A';
          if (d === 'PDM2') return 'Colleague B';
          return d;
        }));

      axisG.select(".domain").attr("stroke", "#e2e8f0");
      axisG.selectAll(".tick line").attr("stroke", "#e2e8f0");
      axisG.selectAll('text')
        .style("font-size", "12px")
        .style("font-family", "'JetBrains Mono', monospace")
        .style("font-weight", "500")
        .style("fill", "#94a3b8")
        .attr('dy', '1.4em')
        .style('text-anchor', 'middle')
        .attr('transform', null);

      axisG.selectAll('text')
        .filter(function(d) { return d === "Me"; })
        .style("text-decoration", "underline")
        .style("fill", "#6366f1")
        .style("font-weight", "600");
    },
    drawYAxis() {
        const axisConfigs = [
            { key: "Me", ref: this.$refs.axisYMe, class: "yaxisMe" },
            { key: "PDM1", ref: this.$refs.axisYPDM1, class: "yaxisPDM1" },
            { key: "PDM2", ref: this.$refs.axisYPDM2, class: "yaxisPDM2" }
        ];

        axisConfigs.forEach(({ key, ref, class: className }) => {
            const xPos = this.xScale(key) + this.xScale.bandwidth() / 2;

            const axisG = d3.select(ref)
              .attr("class", className)
              .attr("transform", `translate(${xPos}, 9)`)
              .call(d3.axisLeft(this.yScale).tickFormat(d => d * 100).tickSize(3));

            axisG.select(".domain").attr("stroke", "none");
            axisG.selectAll(".tick line").attr("stroke", "#e2e8f0");
            axisG.selectAll('text')
              .style("font-size", "11px")
              .style("font-family", "'JetBrains Mono', monospace")
              .style("fill", "#94a3b8");
        });
      
      let scoreText = d3.select(".score-text"); // Check if the "Score" text already exists
      if (scoreText.empty()) {
        d3.select(this.$refs.axisY)
        .append('text')
        // .attr('transform', 'rotate(-90)')
        .attr('y', 6.5)
        .attr('x', 42)
        .attr('dy', '0.71em')
        .attr('text-anchor', 'end')
        .attr('fill', '#94a3b8')
        .attr('class', "score-text")
        .attr('font-family', "'Inter', sans-serif")
        .attr('font-size', '11px')
        .attr('font-weight', '600')
        .text("Score (0-100)");
      }
    },
    drawScatterPlot(amsScoreMe, amsScorePDM1, amsScorePDM2, mode = 'default') {
      const barsGroup = d3.select(this.$refs.barsGroup);

      this.drawBackground(barsGroup);

      // Draw dots for each category
      let yScale = d3.scaleLinear()
        .domain([0, 101.3])
        .rangeRound([this.svgHeight - this.svgPadding.top - this.svgPadding.bottom, 0]);

      //for ME
      this.drawSingleScatter({
        group: barsGroup,
        data: amsScoreMe,
        className: 'dot',
        idPrefix: 'p',
        category: 'Me',
        yScale,
        originalColors: this.originalColors,
        mode,
        animate: this.shouldAnimate,
        fullfeature: this.fullFeature,
        pool: 1,
        filterbuttonClick: this.filterbuttonClick,
      });

      //for PDM1
      this.drawSingleScatter({
        group: barsGroup,
        data: amsScorePDM1,
        className: 'dot_1',
        idPrefix: 'p_1',
        category: 'PDM1',
        yScale,
        originalColors: this.originalColors_1,
        mode,
        animate: this.shouldAnimate,
        fullfeature: this.fullFeature_pdm1,
        pool: 2,
        filterbuttonClick: this.filterbuttonClick,
      });

      //for PDM2
      this.drawSingleScatter({
        group: barsGroup,
        data: amsScorePDM2,
        className: 'dot_2',
        idPrefix: 'p_2',
        category: 'PDM2',
        yScale,
        originalColors: this.originalColors_2,
        mode,
        animate: this.shouldAnimate,
        fullfeature: this.fullFeature_pdm2,
        pool: 3,
        filterbuttonClick: this.filterbuttonClick,
      });

      // If in density mode, draw axis for each category
      if (mode === 'density') {
        this.drawDensityAxes('Me');
        this.drawDensityAxes('PDM1');
        this.drawDensityAxes('PDM2');
      } else {
        this.resetDensityAxes();
      }

    },
    drawBars() {
      let tooltip = d3.select("body").select(".bars-tooltip");
      if (tooltip.empty()) {
        tooltip = d3.select("body")
          .append("div")
          .attr("class", "bars-tooltip")
          .style("position", "absolute")
          .style("opacity", 0)
          .style("background", "rgba(255,255,255,0.96)")
          .style("border", "1px solid rgba(255,255,255,0.82)")
          .style("padding", "10px 14px")
          .style("pointer-events", "none")
          .style("font-size", "12px")
          .style("font-family", "'Inter', sans-serif")
          .style("border-radius", "12px")
          .style("box-shadow", "0 8px 24px rgba(99,102,241,0.12), 0 1px 4px rgba(0,0,0,0.06)");
      }

      const chartWidth = Math.max(this.barSvgWidth - 60, 100);
      const barHeight = 30;

      //gap between the "Individual Score" title to the score distribution bars
      const gap = 83
      const spacing = 30;
      d3.select(".visualizationgroups").remove();
      var barsGroup = d3.select("#second-svg").append("g").attr("class", "visualizationgroups");

      //scale here
      const x = d3.scaleLinear()
        .domain([-0.35, 0.63])
        .range([0, chartWidth]);

      //draw x axis here
      const xAxis = d3.axisBottom(x)
        .ticks(20)
        .tickFormat(d => (d * 100).toFixed(0));

      barsGroup.append("g")
        .attr("class", "x-axis")
        .attr("transform", `translate(${29.5}, ${(barHeight + spacing) * 7 + gap + spacing})`)
        .call(xAxis)
        .selectAll("text")
        .style("font-size", "10px")
        .style("font-family", "'JetBrains Mono', monospace")
        .style("fill", "#94a3b8");

      const bars = barsGroup.selectAll("rect").data(this.features, d => d.id);
      bars.exit().remove();

      const offset = 30;
      bars.enter()
        .append("rect")
        .merge(bars)
        .attr("class", "bar")
        .attr("x", d => d.value >= 0 ? x(0) + offset : x(d.value) + offset)
        .attr("y", (_, i) => i * (barHeight + spacing) + gap)
        .attr("width", d => Math.abs(x(d.value) - x(0)))
        .attr("height", barHeight - 2)
        .attr("fill", d => (d.value >= 0 ? "#10b981" : "#ef4444"))
        .on("mouseover", (event, d) => {
          console.log(d)
          tooltip.transition().duration(200).style("opacity", 0.9);

          tooltip.html(`<div style="font-weight:600;color:#334155;font-size:12px;margin-bottom:4px">${d.name}</div><div style="color:#94a3b8;font-size:11px;margin-bottom:2px">Impact Score</div><div style="font-family:'JetBrains Mono',monospace;font-size:14px;font-weight:500;color:${d.value>=0?'#10b981':'#ef4444'}">${d.value >= 0 ? '+' : ''}${((d.value * 100).toPrecision(2))}</div>`)
            .style("left", (event.pageX + 10) + "px")
            .style("top", (event.pageY - 28) + "px");

        })
        .on("mouseout", () => {
          tooltip.transition().duration(500).style("opacity", 0);
        });


      const profileLabels = Object.entries(this.profile)
        .filter(([key]) => key !== "pid" && key !== "pool")
        .map(([key, value]) => `${key}: ${value} `);


      barsGroup.selectAll(".bar-label")
        .data(profileLabels)
        .enter()
        .append("text")
        .attr("class", "bar-label")
        .attr("x", x(0) + offset - 5)
        .attr("y", (_, i) => i * (barHeight + spacing) + gap - 8)
        .attr("text-anchor", "end")
        .attr("alignment-baseline", "left")
        .attr("font-size", "11px")
        .attr("font-family", "'Inter', sans-serif")
        .attr("fill", "#64748b")
        .text(d => d);

      d3.selectAll(".scorecomposite").remove();

      barsGroup.append("text")
        .attr("class", "scorecomposite")
        .attr("x", 16)
        .attr("y", 38)
        .attr("font-size", "15px")
        .attr("font-family", "'Inter', sans-serif")
        .attr("font-weight", "600")
        .attr("fill", "#6366f1")
        .text("Individual Score: " + Number((this.individualScore).toPrecision(2)));

      barsGroup.append("text")
        .attr("class", "scorecomposite")
        .attr("x", 16)
        .attr("y", 498)
        .attr("font-size", "13px")
        .attr("font-family", "'Inter', sans-serif")
        .attr("font-weight", "600")
        .attr("fill", "#475569")
        .text("Summary: ");

      const positiveFeatures = this.features.filter(f => f.value >= 0);
      const negativeFeatures = this.features.filter(f => f.value < 0);


      let cumilativeNegX = 0;
      let cumilativePosX = 0;

      negativeFeatures.forEach(f => {
        const width = Math.abs(x(f.value) - x(0));

        barsGroup.append("rect")
          .attr("class", "bars")
          .attr("x", x(0) - width + cumilativeNegX + offset)
          .attr("y", (barHeight + spacing) * 7 + gap + 26 + spacing)
          .attr("width", width)
          .attr("height", barHeight - 2)
          .attr("fill", "#ef4444")
          .attr("stroke", "white")

        cumilativeNegX -= width;
      });

      positiveFeatures.forEach(f => {
        const width = x(f.value) - x(0);

        barsGroup.append("rect")
          .attr("class", "bars")
          .attr("x", x(0) + cumilativePosX + offset)
          .attr("y", (barHeight + spacing) * 7 + gap + 26 + spacing)
          .attr("width", width)
          .attr("height", barHeight - 2)
          .attr("fill", "#10b981")
          .attr("stroke", "white")

        cumilativePosX += width;
      });


      const negative = negativeFeatures.reduce((sum, val) => sum + val.value, 0);
      const positive = positiveFeatures.reduce((sum, val) => sum + val.value, 0);

      const negOverlay = barsGroup.append("rect")
        .attr("x", x(0) + cumilativeNegX + offset)
        .attr("y", (barHeight + spacing) * 7 + gap + 26 + spacing)
        .attr("width", Math.abs(cumilativeNegX))
        .attr("height", barHeight - 2)
        .attr("fill", "rgba(239, 68, 68, 0.1)")
        .attr("stroke", "none")
        .on("mouseover", (event) => {
          tooltip.transition().duration(200).style("opacity", 0.9);
          tooltip.html(`<div style="font-weight:600;color:#334155;font-size:12px;margin-bottom:4px">Total Negative Impact</div><div style="font-family:'JetBrains Mono',monospace;font-size:14px;font-weight:500;color:#ef4444">-${Math.abs(negative * 100).toFixed(0)}</div>`)
            .style("left", (event.pageX + 10) + "px")
            .style("top", (event.pageY - 28) + "px");
          negOverlay.attr("fill", "rgba(255, 255, 255, 0.6)");
        })
        .on("mouseout", () => {
          tooltip.transition().duration(500).style("opacity", 0);
          negOverlay.attr("fill", "rgba(239, 68, 68, 0.1)");
        });

      const posOverlay = barsGroup.append("rect")
        .attr("x", x(0) + offset)
        .attr("y", (barHeight + spacing) * 7 + gap + 26 + spacing)
        .attr("width", cumilativePosX)
        .attr("height", barHeight - 2)
        .attr("fill", "rgba(16, 185, 129, 0.1)")
        .attr("stroke", "none")
        .on("mouseover", (event) => {
          tooltip.transition().duration(200).style("opacity", 0.9);
          tooltip.html(`<div style="font-weight:600;color:#334155;font-size:12px;margin-bottom:4px">Total Positive Impact</div><div style="font-family:'JetBrains Mono',monospace;font-size:14px;font-weight:500;color:#10b981">+${(positive * 100).toFixed(0)}</div>`)
            .style("left", (event.pageX + 10) + "px")
            .style("top", (event.pageY - 28) + "px");
          posOverlay.attr("fill", "rgba(255, 255, 255, 0.6)");
        })
        .on("mouseout", () => {
          tooltip.transition().duration(500).style("opacity", 0);
          posOverlay.attr("fill", "rgba(16, 185, 129, 0.1)");
        });
    },
    drawSingleScatter({ group, data, className, idPrefix, category, yScale, originalColors, mode, animate, fullfeature, pool}) {
        const defaultX = this.xScale(category) + this.xScale.bandwidth() / 2 ;
        computeDensityPositions(this.xScale, data, category);
        
        const isFiltering = this.filterbuttonClick;

        const selection = group.selectAll('.' + className)
            .data(data, d => d.pid)
            .join(
                enter => {
                    const sel = enter.append("circle")
                        .attr("class", className)
                        .attr("r", 6)
                        .attr("fill", d => {
                            let color = '#6366f1';
                            originalColors[d.pid] = color;
                            return color;
                        })
                        .attr("opacity", 0)
                        .attr("id", d => idPrefix + d.pid)
                        .attr("stroke", "none")
                        .attr("cx", defaultX)
                        .attr("cy", d => yScale(d.value))
                        .on('mouseover', (event) => {
                            if (this.currentMode === 'density') {
                                d3.select(event.target)
                                    .attr('r', 10)
                                    .style('stroke', 'blue')
                                    .style('stroke-width', 5);
                            }
                        }).on('mouseout', (event, d) => {
                            if (this.currentMode === 'density') {
                                if (!this.selectedDots.includes(+d.pid)) {
                                    d3.select(event.target)
                                        .attr('r', 6)
                                        .style('stroke', 'none')
                                        .style('stroke-width', 1)
                                        .style('fill', originalColors[d.pid] || '#6366f1');
                                }
                            }
                        }).on('click', (event, d) => {
                            if (this.currentMode === 'density') {
                                d3.selectAll("circle").attr("r", 6).style('stroke', 'none')
                                    .style('stroke-width', 1).style('fill', originalColors[d.pid] || '#6366f1');

                                this.selectedDots.push(+d.pid);
                                d3.select(event.target)
                                    .attr('r', 10)
                                    .style('stroke', 'blue')
                                    .style('stroke-width', 5);

                                const selectedEntry = fullfeature.find(entry => entry.pid === d.pid);
                                this.updatingProfile(selectedEntry, pool, d.value);
                                this.drawBars();
                            }
                        });
                    gsap.to(sel.nodes(), { opacity: 0.15, duration: 0.35, delay: isFiltering ? 0.2 : 0 });
                    return sel;
                },
                update => {
                    if (isFiltering) {
                        gsap.fromTo(update.nodes(), { opacity: 0.04 }, { opacity: 0.15, duration: 0.35, delay: 0.1 });
                    }
                    return update;
                },
                exit => {
                    if (isFiltering) {
                        gsap.to(exit.nodes(), { opacity: 0, duration: 0.18, onComplete: () => exit.remove() });
                        return exit;
                    }
                    return exit.remove();
                }
            );

        // Then transition depending on mode
        if(animate & !this.filterbuttonClick){
            selection.transition()
                .duration(800)
                .attr("cx", d => mode === "default" ? defaultX: d._xDensity)
                .attr("cy", d => yScale(d.value));
        }else{
            selection
                .attr("cx", d => mode === "default" ? defaultX : d._xDensity)
                .attr("cy", d => yScale(d.value));
        }

    },
    drawBackground(refGroup) {
      const boarderHeight = this.svgHeight - this.svgPadding.top - this.svgPadding.bottom;
      const bgWidth = this.chartWidth;

      const zones = [
        { id: 'zonebg-high', y: 6,                        h: 0.4 * boarderHeight,        fill: 'rgba(16,185,129,0.12)'  },
        { id: 'zonebg-mid',  y: 0.4 * boarderHeight + 6,  h: 0.2 * boarderHeight,        fill: 'rgba(250,204,21,0.10)'  },
        { id: 'zonebg-low',  y: 0.6 * boarderHeight + 6,  h: 0.4 * boarderHeight - 6,   fill: 'rgba(239,68,68,0.11)'   },
      ];

      zones.forEach(({ id, y, h, fill }) => {
        let rect = refGroup.select(`#${id}`);
        if (rect.empty()) rect = refGroup.append("rect").attr("id", id);
        rect.attr("x", 1).attr("y", y).attr("width", bgWidth).attr("height", h).attr("fill", fill);
      });

      // Zone labels on right edge
      const zoneLabelX = bgWidth - 4;
      const zoneLabels = [
        { id: 'zl-high', y: boarderHeight * 0.18, text: 'HIGH', color: '#10b981' },
        { id: 'zl-mid',  y: boarderHeight * 0.50, text: 'MED',  color: '#94a3b8' },
        { id: 'zl-low',  y: boarderHeight * 0.82, text: 'LOW',  color: '#ef4444' },
      ];
      zoneLabels.forEach(({ id, y, text, color }) => {
        let lbl = refGroup.select(`#${id}`);
        if (lbl.empty()) lbl = refGroup.append("text").attr("id", id);
        lbl.attr("x", zoneLabelX).attr("y", y + 6)
          .attr("text-anchor", "end")
          .attr("font-size", "9px")
          .attr("font-family", "'Inter', sans-serif")
          .attr("font-weight", "700")
          .attr("letter-spacing", "0.08em")
          .attr("fill", color)
          .attr("opacity", "0.55")
          .text(text);
      });
    },
    updatingProfile(selectedEntry, pool, individualScore){
      //linking process
      const scoreDataMap = {
        1: this.detailedScore,
        2: this.detailedScore_1,
        3: this.detailedScore_2
      };

      this.individualScore = individualScore;

      let contributions = linkProfileCard(scoreDataMap, this.profile, selectedEntry, pool);

      for (var i = 0; i < this.features.length; i++) {
        this.features[i].value = contributions[i];
      }   

    },
    drawDensityAxes(key) {
        const ref = {
            "Me": this.$refs.axisYMe,
            "PDM1": this.$refs.axisYPDM1,
            "PDM2": this.$refs.axisYPDM2
        }[key];

        const originalX = this.xScale(key) + this.xScale.bandwidth() / 2;
        const shiftedX = originalX - this.xScale.bandwidth() / 2;

        const axisG = d3.select(ref)
            .call(d3.axisLeft(this.yScale).ticks(20).tickFormat(d => Math.round(d * 100)).tickSize(3));

        axisG.select(".domain").attr("stroke", "none");
        axisG.selectAll(".tick line").attr("stroke", "#e2e8f0");
        axisG.selectAll("text")
            .style("font-size", "11px")
            .style("font-family", "'JetBrains Mono', monospace")
            .style("fill", "#94a3b8");

        axisG.transition().duration(500).attr("transform", `translate(${shiftedX}, 9)`);
    },
    resetDensityAxes() {
        const axisConfigs = [
            { key: "Me", ref: this.$refs.axisYMe },
            { key: "PDM1", ref: this.$refs.axisYPDM1 },
            { key: "PDM2", ref: this.$refs.axisYPDM2 }
        ];

        axisConfigs.forEach(({ key, ref }) => {
            const xPos = this.xScale(key) + this.xScale.bandwidth() / 2;

            const axisG = d3.select(ref)
                .call(d3.axisLeft(this.yScale).tickFormat(d => d * 100).tickSize(3));

            axisG.select(".domain").attr("stroke", "none");
            axisG.selectAll(".tick line").attr("stroke", "#e2e8f0");
            axisG.selectAll("text")
                .style("font-size", "11px")
                .style("font-family", "'JetBrains Mono', monospace")
                .style("fill", "#94a3b8");

            axisG.transition().duration(500).attr("transform", `translate(${xPos}, 9)`);
        });
    },
    handleBarClick(val) {
      this.$store.commit('changeSelectedState', val);
    }
  },
  computed: {
    amsScore:{
      get() {
        return this.$store.getters.amsScore;
      }
    },
    amsScore_1:{
      get() {
        return this.$store.getters.amsScore_1;
      }
    },
    amsScore_2:{
      get() {
        return this.$store.getters.amsScore_2;
      }
    },
    fullFeature:{
      get() {
        return this.$store.getters.fullFeature;
      }
    },
    fullFeature_pdm1:{
      get() {
        return this.$store.getters.amsScore_1_fullFeature;
      }
    },
    fullFeature_pdm2:{
      get() {
        return this.$store.getters.amsScore_2_fullFeature;
      }
    },
    detailedScore: {
      get() {
        return this.$store.getters.detailedScore;
      }
    },
    detailedScore_1: {
      get() {
        return this.$store.getters.detailedScore_1;
      }
    },
    detailedScore_2: {
      get() {
        return this.$store.getters.detailedScore_2;
      }
    },
    personaleIncome: {
      get() {
        return this.$store.getters.personaleIncome;
      }
    },
    hasSelection() {
      return this.profile.pid !== "";
    },
    xScale() {
      return d3.scaleBand()
        .domain(["Me", "PDM1", "PDM2"])
        .range([0, this.chartWidth])
    },
    yScale() {
      return d3.scaleLinear()
        .domain([0, 1])
        .rangeRound([this.svgHeight - this.svgPadding.top - this.svgPadding.bottom - 9, 0])
    },
  },
  watch: {
    amsScore: {
      handler() {
        this.drawChart();
      },
      deep: true,
    },
  },
}
</script>

